import type { ApiError, LookupResult, ShortenResult, Stats } from './types.ts';

const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? '' : 's'}`;

export function formatShorten(r: ShortenResult): string {
  return `${r.code} -> ${r.url}`;
}

export function formatLookup(r: LookupResult): string {
  return `${r.code} -> ${r.url} (${plural(r.hits, 'hit')})`;
}

export function formatStats(s: Stats): string {
  return plural(s.count, 'link');
}

export function formatError(e: ApiError): string {
  return `error: ${e.message} (HTTP ${e.status})`;
}

export function usage(): string {
  return [
    'usage: short [--server <url>] [--json] <command>',
    '  shorten <url>   create a short code for url',
    '  lookup <code>   show the url behind a code',
    '  stats           show how many links are stored',
    '  help            show this help',
  ].join('\n');
}
